/**
 * GitHub REST API 封装
 * 使用原生 fetch 调用 GitHub Contents API，无需额外依赖
 *
 * 文档: https://docs.github.com/en/rest/repos/contents
 */

import { logger } from '@lark-apaas/client-toolkit-lite';

export interface GithubConfig {
  token: string;
  owner: string;
  repo: string;
  branch: string;
  basePath: string;
}

export interface GithubFileResult {
  content: string; // base64 encoded content
  sha: string;
  path: string;
  size: number;
  encoding: string;
}

const API_BASE = 'https://api.github.com';

function getHeaders(token: string): Record<string, string> {
  return {
    Authorization: `Bearer ${token}`,
    Accept: 'application/vnd.github+json',
    'Content-Type': 'application/json',
    'X-GitHub-Api-Version': '2022-11-28',
  };
}

/**
 * 拼接完整的 GitHub API 路径，带 basePath 前缀
 * basePath 为空或 '/' → 直接返回 path
 * basePath 如 '/v2' → 拼为 'v2/path'
 */
function buildRepoPath(config: GithubConfig, path: string): string {
  const base = (config.basePath || '').trim();
  const normalizedBase = !base || base === '/' ? '' : base.replace(/^\//, '').replace(/\/$/, '');
  const cleanPath = path.replace(/^\//, '');
  return normalizedBase ? `${normalizedBase}/${cleanPath}` : cleanPath;
}

/**
 * 测试连接：尝试获取仓库信息
 */
export async function testConnection(config: GithubConfig): Promise<{
  success: boolean;
  message: string;
  repoInfo?: {
    fullName: string;
    defaultBranch: string;
    private: boolean;
  };
}> {
  try {
    const url = `${API_BASE}/repos/${config.owner}/${config.repo}`;
    logger.info(`[GitHub API] testConnection: GET ${url}`);
    const response = await fetch(url, { headers: getHeaders(config.token) });

    if (response.status === 404) {
      return { success: false, message: 'Repository not found. Check owner and repo name.' };
    }
    if (response.status === 401 || response.status === 403) {
      const rateRemaining = response.headers.get('x-ratelimit-remaining');
      if (rateRemaining === '0') {
        return { success: false, message: 'API rate limit exceeded. Please wait and try again.' };
      }
      return { success: false, message: 'Authentication failed. Check your Personal Access Token.' };
    }
    if (!response.ok) {
      return { success: false, message: `Connection failed: HTTP ${response.status}` };
    }

    const data = await response.json();
    logger.info(`[GitHub API] testConnection success: full_name=${data.full_name}, default_branch=${data.default_branch}, private=${data.private}`);
    return {
      success: true,
      message: 'Connection successful!',
      repoInfo: {
        fullName: data.full_name,
        defaultBranch: data.default_branch,
        private: data.private,
      },
    };
  } catch (err) {
    return { success: false, message: `Network error: ${err instanceof Error ? err.message : String(err)}` };
  }
}

/**
 * 获取文件内容
 */
export async function getFileContent(
  config: GithubConfig,
  path: string
): Promise<GithubFileResult | null> {
  const repoPath = buildRepoPath(config, path);
  try {
    const url = `${API_BASE}/repos/${config.owner}/${config.repo}/contents/${encodeURI(repoPath)}?ref=${encodeURIComponent(config.branch)}`;
    logger.info(`[GitHub API] getFileContent: GET ${url}`);
    const response = await fetch(url, { headers: getHeaders(config.token) });

    if (response.status === 404) {
      logger.info(`[GitHub API] getFileContent: 404 not found (${repoPath})`);
      return null;
    }
    if (!response.ok) {
      const errText = await response.text().catch(() => '');
      logger.error(`[GitHub API] getFileContent failed: HTTP ${response.status} ${errText.slice(0, 200)}`);
      throw new Error(`GitHub API error: HTTP ${response.status}`);
    }

    const data = await response.json();
    // 如果是目录，返回 null
    if (Array.isArray(data)) {
      return null;
    }
    return {
      content: data.content || '',
      sha: data.sha,
      path: data.path,
      size: data.size,
      encoding: data.encoding,
    };
  } catch (err) {
    logger.error('GitHub getFileContent error:', String(err));
    throw err;
  }
}

/**
 * 创建或更新文件
 * @param config GitHub 配置
 * @param path 文件在仓库中的路径，如 data/products.json
 * @param content 文件内容（字符串或 base64，文本会自动转 base64）
 * @param message commit message
 * @param isBase64 content 是否已经是 base64（图片等二进制文件传 true）
 */
const MAX_RETRIES = 3;
const RETRY_DELAYS_MS = [500, 1000, 2000]; // 指数退避延迟

function sleep(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

export async function createOrUpdateFile(
  config: GithubConfig,
  path: string,
  content: string,
  message: string,
  isBase64 = false
): Promise<{ success: boolean; sha: string; commit: { sha: string; url: string } }> {
  const repoPath = buildRepoPath(config, path);
  logger.info(`[GitHub API] createOrUpdateFile: path=${repoPath}, isBase64=${isBase64}`);

  // 文本内容转 base64
  const base64Content = isBase64
    ? content
    : btoa(unescape(encodeURIComponent(content))); // 支持 UTF-8

  /**
   * 执行一次 PUT 请求。传入 sha 表示更新，不传表示创建。
   */
  async function doPut(sha: string | null): Promise<Response> {
    const body: Record<string, string> = {
      message,
      content: base64Content,
      branch: config.branch,
    };
    if (sha) {
      body.sha = sha;
    }

    const url = `${API_BASE}/repos/${config.owner}/${config.repo}/contents/${encodeURI(repoPath)}`;
    logger.info(
      `[GitHub API] createOrUpdateFile: PUT ${url} (${sha ? `update, sha=${sha.slice(0, 7)}` : 'create new file'})`
    );

    return fetch(url, {
      method: 'PUT',
      headers: getHeaders(config.token),
      body: JSON.stringify(body),
    });
  }

  /**
   * 判断是否是可重试的冲突错误。
   * 409 = SHA mismatch（文件已被其他人修改）
   * 422 且 message 含 "already exists" / "sha" = 创建已存在的文件或 SHA 无效，应重新获取 SHA 后再试
   */
  function isConflictError(status: number, errMsg: string): boolean {
    if (status === 409) return true;
    if (status === 422) {
      const lower = errMsg.toLowerCase();
      // "already exists" — 文件已存在但我们是用创建模式（不带 sha）PUT 的
      // "sha" / "invalid sha" — SHA 不对
      return lower.includes('already exists') || lower.includes('sha');
    }
    return false;
  }

  // 第一步：获取文件最新 SHA（文件不存在则为 null）
  let currentSha: string | null = null;
  const initial = await getFileContent(config, path);
  if (initial && initial.sha) {
    currentSha = initial.sha;
    logger.info(`[GitHub API] createOrUpdateFile: initial sha=${currentSha.slice(0, 7)} (update mode)`);
  } else {
    logger.info('[GitHub API] createOrUpdateFile: file does not exist, will create (create mode)');
  }

  // 第二步：首次尝试 + 最多 MAX_RETRIES 次重试
  let response: Response = await doPut(currentSha);
  let attempts = 1;

  while (attempts <= MAX_RETRIES) {
    // 读取错误体（冲突场景下），用于判断是否可重试
    let errMsg = '';
    if (!response.ok && response.status !== 401 && response.status !== 403 && response.status !== 404) {
      const errData = await response.clone().json().catch(() => ({}));
      errMsg = errData.message || '';
    }

    if (!isConflictError(response.status, errMsg)) {
      break; // 不是冲突类错误，跳出循环走错误处理
    }

    logger.warn(
      `[GitHub API] createOrUpdateFile: conflict (HTTP ${response.status}, msg="${errMsg}"), ` +
        `attempt ${attempts}/${MAX_RETRIES}, will retry after ${RETRY_DELAYS_MS[attempts - 1]}ms`
    );

    // 等待（指数退避）
    await sleep(RETRY_DELAYS_MS[attempts - 1]);

    // 重新获取最新 SHA
    const refreshed = await getFileContent(config, path);
    if (refreshed && refreshed.sha) {
      currentSha = refreshed.sha;
      logger.info(
        `[GitHub API] createOrUpdateFile: refreshed sha=${currentSha.slice(0, 7)} (retry attempt ${attempts})`
      );
    } else {
      // 文件不存在了（被删除），用创建模式重试
      currentSha = null;
      logger.info(
        `[GitHub API] createOrUpdateFile: file no longer exists, switching to create mode (retry attempt ${attempts})`
      );
    }

    response = await doPut(currentSha);
    attempts += 1;
  }

  if (attempts > 1 && !response.ok) {
    logger.warn(
      `[GitHub API] createOrUpdateFile: all ${MAX_RETRIES} retries exhausted, final status=${response.status}`
    );
  } else if (attempts > 1 && response.ok) {
    logger.info(`[GitHub API] createOrUpdateFile: succeeded after ${attempts - 1} retry(ies)`);
  }

  // 第四步：统一处理错误
  if (response.status === 401 || response.status === 403) {
    const rateRemaining = response.headers.get('x-ratelimit-remaining');
    const errData = await response.json().catch(() => ({}));
    const errMsg = errData.message || '';
    logger.error(
      `[GitHub API] createOrUpdateFile auth error: ${response.status}, remaining=${rateRemaining}, message=${errMsg}`
    );
    // 主速率限制耗尽
    if (rateRemaining === '0') {
      throw new Error('GitHub API rate limit exceeded. Please wait a few minutes.');
    }
    // 401 → 真正的认证失败（Token 无效/过期）
    if (response.status === 401) {
      throw new Error('Authentication failed. Check your Personal Access Token permissions.');
    }
    // 403 但还有剩余配额 → secondary rate limit / abuse detection / 权限不足
    if (errMsg.toLowerCase().includes('abuse') || errMsg.toLowerCase().includes('secondary')) {
      throw new Error(
        `GitHub secondary rate limit triggered. Slow down and try again later. (${errMsg})`
      );
    }
    if (errMsg.toLowerCase().includes('permission') || errMsg.toLowerCase().includes('access')) {
      throw new Error(`Permission denied: ${errMsg}`);
    }
    throw new Error(
      `GitHub API request rejected (HTTP 403): ${errMsg || 'unknown reason'}. Check token scope and rate limits.`
    );
  }
  if (response.status === 404) {
    throw new Error('Repository or branch not found.');
  }
  if (response.status === 409) {
    throw new Error(
      `Conflict: the file was modified by someone else. Tried ${MAX_RETRIES + 1} times. Please try again in a moment.`
    );
  }
  if (response.status === 422) {
    const errData = await response.json().catch(() => ({}));
    const errMsg = errData.message || 'Validation failed (HTTP 422)';
    logger.error(`[GitHub API] createOrUpdateFile 422 (final, after retries): ${errMsg}`);
    throw new Error(`Upload failed: ${errMsg}`);
  }
  if (!response.ok) {
    const errData = await response.json().catch(() => ({}));
    const errMsg = errData.message || `GitHub API error: HTTP ${response.status}`;
    logger.error(`[GitHub API] createOrUpdateFile failed: HTTP ${response.status} - ${errMsg}`);
    throw new Error(errMsg);
  }

  const data = await response.json();
  logger.info(`[GitHub API] createOrUpdateFile success: commit=${data.commit?.sha?.slice(0, 7) || 'unknown'}`);
  return {
    success: true,
    sha: data.content?.sha || '',
    commit: {
      sha: data.commit?.sha || '',
      url: data.commit?.html_url || '',
    },
  };
}

/**
 * 删除文件
 */
export async function deleteFile(
  config: GithubConfig,
  path: string,
  message: string
): Promise<boolean> {
  const repoPath = buildRepoPath(config, path);
  const existing = await getFileContent(config, path);
  if (!existing) {
    return true; // 不存在就算成功
  }

  const url = `${API_BASE}/repos/${config.owner}/${config.repo}/contents/${encodeURI(repoPath)}`;
  logger.info(`[GitHub API] deleteFile: DELETE ${url}`);
  const response = await fetch(url,
    {
      method: 'DELETE',
      headers: getHeaders(config.token),
      body: JSON.stringify({
        message,
        sha: existing.sha,
        branch: config.branch,
      }),
    }
  );

  if (!response.ok) {
    const errData = await response.json().catch(() => ({}));
    throw new Error(errData.message || `GitHub API error: HTTP ${response.status}`);
  }
  return true;
}

/**
 * 获取仓库信息
 */
export async function getRepoInfo(config: GithubConfig): Promise<{
  fullName: string;
  defaultBranch: string;
  private: boolean;
  pagesBranch?: string;
}> {
  const url = `${API_BASE}/repos/${config.owner}/${config.repo}`;
  logger.info(`[GitHub API] getRepoInfo: GET ${url}`);
  const response = await fetch(url, { headers: getHeaders(config.token) });

  if (!response.ok) {
    logger.error(`[GitHub API] getRepoInfo failed: HTTP ${response.status}`);
    throw new Error(`Failed to get repo info: HTTP ${response.status}`);
  }

  const data = await response.json();
  return {
    fullName: data.full_name,
    defaultBranch: data.default_branch,
    private: data.private,
  };
}

/**
 * 从 base64 解码内容
 */
export function decodeBase64Content(base64: string): string {
  try {
    return decodeURIComponent(escape(atob(base64)));
  } catch {
    return atob(base64);
  }
}

// ============================================================
// 批量提交：使用 Git Data API 在一个 commit 中上传多个文件
// 流程：获取最新 commit SHA → 创建 blobs → 创建 tree → 创建 commit → 更新 ref
// ============================================================

export interface BatchFileEntry {
  path: string;       // 仓库内相对路径，如 "data/products.json"
  content: string;    // 文件内容（文本或 base64）
  isBase64: boolean;  // content 是否已经是 base64 编码
}

export interface BatchCommitResult {
  success: boolean;
  commitSha: string;
  commitUrl: string;
  fileCount: number;
}

/**
 * 文本内容转 base64（支持 UTF-8）
 */
function toBase64(text: string): string {
  return btoa(unescape(encodeURIComponent(text)));
}

/**
 * 获取指定分支的最新 commit SHA
 */
async function getLatestCommitSha(config: GithubConfig): Promise<string> {
  const ref = `heads/${config.branch}`;
  const url = `${API_BASE}/repos/${config.owner}/${config.repo}/git/ref/${encodeURIComponent(ref)}`;
  logger.info(`[GitHub API] getLatestCommitSha: GET ${url}`);
  const response = await fetch(url, { headers: getHeaders(config.token) });
  if (!response.ok) {
    const errData = await response.json().catch(() => ({}));
    const errMsg = errData.message || `Failed to get ref: HTTP ${response.status}`;
    throw new Error(errMsg);
  }
  const data = await response.json();
  return data.object.sha;
}

/**
 * 获取指定 commit 对应的 tree SHA
 */
async function getTreeShaForCommit(config: GithubConfig, commitSha: string): Promise<string> {
  const url = `${API_BASE}/repos/${config.owner}/${config.repo}/git/commits/${commitSha}`;
  const response = await fetch(url, { headers: getHeaders(config.token) });
  if (!response.ok) {
    throw new Error(`Failed to get commit tree: HTTP ${response.status}`);
  }
  const data = await response.json();
  return data.tree.sha;
}

/**
 * 创建一个 blob，返回 blob SHA
 */
async function createBlob(config: GithubConfig, contentBase64: string): Promise<string> {
  const url = `${API_BASE}/repos/${config.owner}/${config.repo}/git/blobs`;
  const response = await fetch(url, {
    method: 'POST',
    headers: getHeaders(config.token),
    body: JSON.stringify({
      content: contentBase64,
      encoding: 'base64',
    }),
  });
  if (!response.ok) {
    const errData = await response.json().catch(() => ({}));
    const errMsg = errData.message || `Failed to create blob: HTTP ${response.status}`;
    throw new Error(errMsg);
  }
  const data = await response.json();
  return data.sha;
}

/**
 * 批量创建 tree（基于父 tree），返回新 tree SHA
 */
async function createTree(
  config: GithubConfig,
  baseTreeSha: string,
  entries: { path: string; blobSha: string }[]
): Promise<string> {
  const url = `${API_BASE}/repos/${config.owner}/${config.repo}/git/trees`;
  const tree = entries.map((e) => ({
    path: e.path,
    mode: '100644',
    type: 'blob',
    sha: e.blobSha,
  }));
  const response = await fetch(url, {
    method: 'POST',
    headers: getHeaders(config.token),
    body: JSON.stringify({
      base_tree: baseTreeSha,
      tree,
    }),
  });
  if (!response.ok) {
    const errData = await response.json().catch(() => ({}));
    const errMsg = errData.message || `Failed to create tree: HTTP ${response.status}`;
    throw new Error(errMsg);
  }
  const data = await response.json();
  return data.sha;
}

/**
 * 创建一个 commit，返回 commit SHA
 */
async function createCommit(
  config: GithubConfig,
  message: string,
  treeSha: string,
  parentSha: string
): Promise<{ sha: string; html_url: string }> {
  const url = `${API_BASE}/repos/${config.owner}/${config.repo}/git/commits`;
  const response = await fetch(url, {
    method: 'POST',
    headers: getHeaders(config.token),
    body: JSON.stringify({
      message,
      tree: treeSha,
      parents: [parentSha],
    }),
  });
  if (!response.ok) {
    const errData = await response.json().catch(() => ({}));
    const errMsg = errData.message || `Failed to create commit: HTTP ${response.status}`;
    throw new Error(errMsg);
  }
  const data = await response.json();
  return { sha: data.sha, html_url: data.html_url };
}

/**
 * 更新 ref 指向新的 commit
 */
async function updateRef(config: GithubConfig, commitSha: string): Promise<void> {
  const ref = `heads/${config.branch}`;
  const url = `${API_BASE}/repos/${config.owner}/${config.repo}/git/refs/${encodeURIComponent(ref)}`;
  const response = await fetch(url, {
    method: 'PATCH',
    headers: getHeaders(config.token),
    body: JSON.stringify({
      sha: commitSha,
      force: false,
    }),
  });
  if (!response.ok) {
    const errData = await response.json().catch(() => ({}));
    const errMsg = errData.message || `Failed to update ref: HTTP ${response.status}`;
    throw new Error(errMsg);
  }
}

/**
 * 批量提交多个文件到 GitHub，只产生一个 commit，只触发一次 Pages 部署
 *
 * 注意：
 * - 文件数量较多时逐个创建 blob 可能较慢，但比多 commit 少触发多次部署要快得多
 * - 大文件（base64 图片）通过 blob 上传，Contents API 的 1MB 显示限制不适用 Git Data API
 * - 支持 409 冲突重试（重新获取最新 commit 再提交）
 */
export async function createOrUpdateFilesBatch(
  config: GithubConfig,
  files: BatchFileEntry[],
  message: string
): Promise<BatchCommitResult> {
  if (files.length === 0) {
    return { success: true, commitSha: '', commitUrl: '', fileCount: 0 };
  }

  logger.info(`[GitHub API] createOrUpdateFilesBatch: ${files.length} files, message="${message}"`);

  // 预处理：文本转 base64，计算 repoPath
  const normalized = files.map((f) => ({
    repoPath: buildRepoPath(config, f.path),
    base64: f.isBase64 ? f.content : toBase64(f.content),
  }));

  const MAX_RETRIES = 3;
  const RETRY_DELAYS = [500, 1000, 2000];

  for (let attempt = 0; attempt <= MAX_RETRIES; attempt++) {
    try {
      // 1. 获取最新 commit 和 tree
      const latestCommitSha = await getLatestCommitSha(config);
      const baseTreeSha = await getTreeShaForCommit(config, latestCommitSha);
      logger.info(
        `[GitHub API] batch: latest commit=${latestCommitSha.slice(0, 7)}, tree=${baseTreeSha.slice(0, 7)}`
      );

      // 2. 为每个文件创建 blob（串行避免速率限制，并发过大容易 secondary rate limit）
      const treeEntries: { path: string; blobSha: string }[] = [];
      for (const file of normalized) {
        const blobSha = await createBlob(config, file.base64);
        treeEntries.push({ path: file.repoPath, blobSha });
        logger.info(
          `[GitHub API] batch: blob created for ${file.repoPath} (${blobSha.slice(0, 7)})`
        );
      }

      // 3. 创建新 tree
      const newTreeSha = await createTree(config, baseTreeSha, treeEntries);
      logger.info(`[GitHub API] batch: new tree=${newTreeSha.slice(0, 7)}`);

      // 4. 创建 commit
      const { sha: newCommitSha, html_url: commitUrl } = await createCommit(
        config,
        message,
        newTreeSha,
        latestCommitSha
      );
      logger.info(
        `[GitHub API] batch: commit created, sha=${newCommitSha.slice(0, 7)}`
      );

      // 5. 更新 ref
      await updateRef(config, newCommitSha);
      logger.info(`[GitHub API] batch: ref updated, commit=${newCommitSha.slice(0, 7)}`);

      return {
        success: true,
        commitSha: newCommitSha,
        commitUrl,
        fileCount: files.length,
      };
    } catch (err) {
      const msg = err instanceof Error ? err.message : String(err);
      // 409 = 冲突（ref 在我们处理期间被更新了），重试
      const isConflict = msg.toLowerCase().includes('409') || msg.toLowerCase().includes('conflict');
      if (isConflict && attempt < MAX_RETRIES) {
        logger.warn(
          `[GitHub API] batch: conflict on attempt ${attempt + 1}, retrying after ${RETRY_DELAYS[attempt]}ms`
        );
        await sleep(RETRY_DELAYS[attempt]);
        continue;
      }
      logger.error(`[GitHub API] batch commit failed: ${msg}`);
      throw err;
    }
  }

  // 理论不会到这里
  throw new Error('Batch commit failed after all retries.');
}
